/// <summary>
/// This is an extension class for PurchLineOpenOrder form PurchLine datasource.
/// </summary>
[ExtensionOf(FormDataSourcestr(PurchLineOpenOrder, PurchLine))]
final class METPurchLineOpenOrderPurchLineDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Filters the purchase order lines based on item number, Vendor account and status.
    /// </summary>
    public void executeQuery()
    {
        FormDataSource purchLineDataSource = this as FormDataSource;
        FormRun formRun = purchLineDataSource.formRun();

        if (formRun.args().menuItemName() == menuItemDisplayStr(METPurchTableListPage))
        {
            ReqItemTable reqItemTable;
            InventDim inventDim;

            METVendorChangeRequest vendorChangeRequest = formRun.args().record();

            select firstonly VendId, ItemId, RecId from reqItemTable
                exists join inventDim
                where inventDim.inventDimId == reqItemTable.CovInventDimId
                    && reqItemTable.ItemId == vendorChangeRequest.ItemId
                    && inventDim.InventLocationId == vendorChangeRequest.InventLocationId
                    && inventDim.InventSiteId == vendorChangeRequest.SiteId;

            QueryBuildDataSource purchLineQueryRunQbds = purchLineDataSource.queryBuildDataSource();
            
            purchLineQueryRunQbds.addRange(fieldNum(PurchLine, ItemId)).value(vendorChangeRequest.ItemId);
            purchLineQueryRunQbds.addRange(fieldNum(PurchLine, VendAccount)).value(reqItemTable.VendId);
            purchLineQueryRunQbds.addRange(fieldNum(PurchLine, PurchStatus)).value(enum2Str(PurchStatus::Backorder));

            FormDataSource inventDimDataSource = formRun.dataSource(FormDataSourcestr(PurchLineOpenOrder, InventDim));

            if (inventDimDataSource != null)
            {
                inventDimDataSource.executeQuery();
            }
        }

        next executeQuery();
        
    }
